import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { LedgerEntry, LedgerDirection } from './ledger.entity';

export interface InvariantResult {
  balanced: boolean;
  totalCredit: string;
  totalDebit: string;
}

@Injectable()
export class LedgerService {
  constructor(
    @InjectRepository(LedgerEntry)
    private readonly ledgerRepository: Repository<LedgerEntry>,
  ) {}

  // Runs on EVERY call to GET /ledger/invariant: two full-table aggregations
  // over the whole ledger, one per direction, no matter how much of that
  // history is old and can never change again.
  async verifyInvariant(): Promise<InvariantResult> {
    const creditRow = await this.ledgerRepository
      .createQueryBuilder('ledger')
      .select('SUM(ledger.amount)', 'total')
      .where('ledger.direction = :direction', { direction: LedgerDirection.CREDIT })
      .getRawOne<{ total: string }>();

    const debitRow = await this.ledgerRepository
      .createQueryBuilder('ledger')
      .select('SUM(ledger.amount)', 'total')
      .where('ledger.direction = :direction', { direction: LedgerDirection.DEBIT })
      .getRawOne<{ total: string }>();

    const totalCredit = creditRow?.total ?? '0';
    const totalDebit = debitRow?.total ?? '0';

    return {
      balanced: totalCredit === totalDebit,
      totalCredit,
      totalDebit,
    };
  }
}

// ledger.controller.ts
import { Controller, Get } from '@nestjs/common';
import { LedgerService, InvariantResult } from './ledger.service';

@Controller('ledger')
export class LedgerController {
  constructor(private readonly ledgerService: LedgerService) {}

  @Get('invariant')
  async checkInvariant(): Promise<InvariantResult> {
    return this.ledgerService.verifyInvariant();
  }
}
